"use client";

import { Amplify } from "aws-amplify";
import React, { useEffect, useState } from "react";

export default function AmplifyProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  // Block rendering until Amplify is configured so that generateClient calls
  // in child components don't fire before the config arrives. On slow networks
  // the original fire-and-forget useEffect would cause silent empty results.
  const [configured, setConfigured] = useState(false);

  useEffect(() => {
    // amplify_outputs.json is generated by 'npx ampx sandbox' and is not
    // committed to the repository. We load it at runtime via a fetch so the
    // build does not fail when the file is absent (e.g. fresh CI clone).
    fetch("/amplify_outputs.json")
      .then((res) => {
        if (!res.ok) return;
        return res.json();
      })
      .then((outputs) => {
        if (outputs) {
          Amplify.configure(outputs, { ssr: true });
        }
      })
      .catch(() => {
        // amplify_outputs.json not yet generated; run 'npx ampx sandbox' first.
      })
      .finally(() => {
        // Unblock rendering regardless of success/failure so the app always
        // renders. If config failed, data calls will error gracefully.
        setConfigured(true);
      });
  }, []);

  if (!configured) {
    // Show nothing until Amplify is configured to prevent data calls firing
    // before config arrives. A short loading indicator is intentionally
    // omitted here — the individual pages manage their own loading states.
    return null;
  }

  return <>{children}</>;
}
